const groups={identity:'Identity',custom_tags:'Custom tags',factions:'Factions',stats:'Stats',health_track:'Health track',abilities:'Abilities',signature_move:'Signature move',links:'Character links',eligibility:'Troupe eligibility'};
const help={custom_tags:'Assigned from the card. Add or edit tags here.',identity:'Confirm the name, printed version, keywords and base diameter.',factions:'Check every faction symbol. A character can belong to more than one faction.',stats:'Confirm the printed numbers, including negative Evade. Leave special values blank and explain them in the review note.',health_track:'Dots are ordered from left to right. Check blue for each energy dot.',abilities:'Keep the complete wording of every rule, including timing, target restrictions, results and catastrophes. Arcane colours refer to the result symbols.',signature_move:'Confirm the full text, damage table and highlighted outcomes. A blank damage value means the no-damage symbol; zero means a printed zero.',links:'Add official character, miniature or product pages. The official PDF link always remains attached to the card.',eligibility:'Selectable or summon.'};
let cards=[],revision=0,sourceHash='',current=null,group='identity',draft={},dirty=false,touched=new Set();
const $=id=>document.getElementById(id);
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e}
const clone=v=>JSON.parse(JSON.stringify(v));
function valuesFor(c,g){if(g==='identity')return Object.fromEntries(['name','keywords','base_size_mm','card_version'].map(k=>[k,clone(c[k])]));if(g==='links')return {character_urls:clone(c.source.character_urls)};return {[g]:clone(c[g])}}
function entry(g){return draft[g]??(draft[g]={values:valuesFor(current,g),status:current.review.fields[g]||'needs_review',note:''})}
function changed(g=group){dirty=true;touched.add(g);$('message').textContent='Unsaved changes';updateWholeStatus();}
function field(parent,label,value,fn,type='text'){
 const fieldGroup=group;const id='f-'+Math.random().toString(36).slice(2);const l=el('label',label);l.htmlFor=id;const input=el(type==='textarea'?'textarea':'input');input.id=id;if(type!=='textarea')input.type=type;input.value=value??'';input.addEventListener('input',()=>{fn(type==='number'?(input.value===''?null:Number(input.value)):input.value);const e=entry(fieldGroup);e.status='needs_review';changed(fieldGroup)});parent.append(l,input);return input;
}
function lines(v){return v.split('\n').map(x=>x.trim()).filter(Boolean)}
function select(parent,label,value,options,fn){const fieldGroup=group;const l=el('label',label);const s=el('select');const id='s-'+Math.random().toString(36).slice(2);s.id=id;l.htmlFor=id;for(const [k,v] of options){const o=el('option',v);o.value=k;s.append(o)}s.value=value;s.addEventListener('change',()=>{fn(s.value);changed(fieldGroup)});parent.append(l,s);return s}
function dirtySelect(parent,label,value,options,fn){const fieldGroup=group;return select(parent,label,value,options,v=>{fn(v);entry(fieldGroup).status='needs_review';updateWholeStatus()})}
function renderList(){const q=$('search').value.toLowerCase(),f=$('filter').value;const list=$('list');list.replaceChildren();let count=0;for(const c of cards){const verified=c.review.status==='verified';if(f==='verified'&&!verified||f==='pending'&&verified||!(c.name+' '+c.keywords.join(' ')+' '+c.custom_tags.join(' ')).toLowerCase().includes(q))continue;count++;const b=el('button',c.name);if(current?.id===c.id)b.className='active';b.append(el('small',`Card ${c.source.pdf_page} · ${Object.values(c.review.fields).filter(s=>s==='verified').length}/9 fields`));b.onclick=()=>openCard(c);list.append(b)}if(!count)list.append(el('p','No matching cards.'));const complete=cards.filter(c=>c.review.status==='verified').length;$('progress').textContent=`${complete} of ${cards.length} cards verified`}
function updateWholeStatus(){if(current)$('verify').textContent=Object.values(draft).every(e=>e.status==='verified')?'Reconfirm and save whole card':'Verify and save whole card'}
function openCard(c){if(dirty&&!window.confirm('Discard unsaved changes for this card?'))return;current=c;draft={};dirty=false;touched=new Set();for(const g of Object.keys(groups)){draft[g]={values:valuesFor(c,g),status:c.review.fields[g]||'needs_review',note:c.review.notes?.[g]||''}}$('name').textContent=c.name;$('page').textContent=`CARD ${c.source.pdf_page} / ${cards.length} · ${c.factions.join(' / ')||'Faction unresolved'}`;$('card').src='/'+c.source.image_path+'?quality=360';$('card').alt=`Original cards for ${c.name}`;$('official').href=c.source.card_url;$('raw').textContent=c.raw_front_text+'\n\n'+c.raw_back_text;$('zoom').value=100;$('card').style.width='100%';$('message').textContent='Compare each field with the original card.';renderList();renderEditor();updateWholeStatus()}
function renderEditor(){const editor=$('editor');editor.replaceChildren();for(const g of Object.keys(groups)){group=g;renderGroup(g)}updateWholeStatus()}
function renderGroup(group){const editor=$('editor');const panel=el('div',undefined,'panel');panel.append(el('h3',groups[group]),el('p',help[group],'help'));for(const issue of current.review.issues||[]){if(issue.field.split('.')[0]===group&&!['needs_review','verified'].includes(issue.code))panel.append(el('p',issue.message,'issue'))}editor.append(panel);const e=entry(group),v=e.values;
 if(group==='custom_tags')field(panel,'Custom tags (one per line)',v.custom_tags.join('\n'),x=>v.custom_tags=[...new Set(lines(x))],'textarea');
 if(group==='identity'){field(panel,'Character name',v.name,x=>v.name=x);field(panel,'Keywords (one per line)',v.keywords.join('\n'),x=>v.keywords=lines(x),'textarea');const r=el('div',undefined,'row');panel.append(r);field(r,'Base size (mm)',v.base_size_mm,x=>v.base_size_mm=x,'number');field(r,'Printed card version',v.card_version,x=>v.card_version=x,'number')}
 if(group==='factions'){const row=el('div',undefined,'checks');panel.append(row);for(const f of ['Commonwealth','Dominion','Leshavult','Shades']){const l=el('label');const i=el('input');i.type='checkbox';i.checked=v.factions.includes(f);i.onchange=()=>{v.factions=i.checked?[...v.factions,f]:v.factions.filter(x=>x!==f);e.status='needs_review';changed(group);updateWholeStatus()};l.append(i,document.createTextNode(f));row.append(l)}}
 if(group==='stats'){const r=el('div',undefined,'row');panel.append(r);for(const [k,label] of Object.entries({melee:'Melee',melee_range_inches:'Melee range (inches)',arcane:'Arcane',evade:'Evade',health:'Health',energy:'Energy'}))field(r,label,v.stats[k],x=>v.stats[k]=x,'number')}
 if(group==='health_track'){const row=el('div');panel.append(row);v.health_track.forEach((d,j)=>{const l=el('label',undefined,'dot');const i=el('input');i.type='checkbox';i.checked=d.energy;i.onchange=()=>{d.energy=i.checked;e.status='needs_review';changed(group);updateWholeStatus()};l.append(i,document.createTextNode(`${j+1} blue`));row.append(l)});const add=el('button','Add health dot');add.onclick=()=>{v.health_track.push({energy:false});e.status='needs_review';changed(group);renderEditor();updateWholeStatus()};const remove=el('button','Remove last dot');remove.onclick=()=>{v.health_track.pop();e.status='needs_review';changed(group);renderEditor();updateWholeStatus()};panel.append(add,document.createTextNode(' '),remove,el('p','Keep total health and energy in Stats consistent with this track.','help'))}
 if(group==='abilities'){v.abilities.forEach((a,j)=>{const box=el('div',undefined,'ability');box.append(el('h4',`Ability ${j+1}`));panel.append(box);field(box,'Name',a.name,x=>a.name=x);dirtySelect(box,'Type',a.category,[['passive','Passive'],['action','Action'],['arcane_action','Arcane action']],x=>a.category=x);const r=el('div',undefined,'row');box.append(r);field(r,'Energy cost',a.energy_cost,x=>a.energy_cost=x,'number');field(r,'Range (inches)',a.range_inches,x=>a.range_inches=x,'number');field(box,'Complete rule text',a.text,x=>a.text=x,'textarea');field(box,'Arcane colours (comma separated)',(a.arcane_colours||[]).join(', '),x=>a.arcane_colours=x.split(',').map(s=>s.trim()).filter(Boolean));const del=el('button','Remove ability');del.onclick=()=>{v.abilities.splice(j,1);e.status='needs_review';changed(group);renderEditor();updateWholeStatus()};box.append(del)});const add=el('button','Add ability');add.onclick=()=>{v.abilities.push({name:'New ability',category:'passive',energy_cost:null,range_inches:null,text:'',arcane_colours:[]});e.status='needs_review';changed(group);renderEditor();updateWholeStatus()};panel.append(add)}
 if(group==='signature_move'){const a=v.signature_move;field(panel,'Move name',a.name,x=>a.name=x||null);field(panel,'Upgrade for',a.upgrade_for,x=>a.upgrade_for=x||null);field(panel,'Damage type',a.damage_type,x=>a.damage_type=x||null);const r=el('div',undefined,'row');panel.append(r);for(const move of ['High Guard','Falling Swing','Thrust','Sweeping Cut','Rising Attack','Low Guard'])field(r,move,a.damage_table[move],x=>a.damage_table[move]=x,'number');field(panel,'Highlighted outcomes (one per line)',(a.highlighted_outcomes||[]).join('\n'),x=>a.highlighted_outcomes=lines(x),'textarea');field(panel,'Complete signature card text',a.text,x=>a.text=x,'textarea')}
 if(group==='links')field(panel,'Official character links (one per line)',v.character_urls.join('\n'),x=>v.character_urls=lines(x),'textarea');
 if(group==='eligibility'){const a=v.eligibility;dirtySelect(panel,'Troupe eligibility',a.summoned_only?'summon':'selectable',[['selectable','Selectable'],['summon','Summon']],x=>{a.selectable=x==='selectable';a.summoned_only=x==='summon'})}
 if(group!=='eligibility')field(panel,'Review note',e.note,x=>e.note=x,'textarea');
}
async function load(){const r=await fetch('/api/cards');if(!r.ok)throw new Error('Could not load the catalogue.');const data=await r.json();cards=data.cards;revision=data.revision;sourceHash=data.source_hash;return cards}
async function saveReview(){if(!current||!dirty)return false;const button=$('save');button.disabled=true;try{const r=await fetch('/api/review',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({page:current.source.pdf_page,source_hash:sourceHash,revision,groups:Object.fromEntries([...touched].map(g=>[g,draft[g]]))})});const response=await r.json();if(!r.ok)throw new Error(response.error);const page=current.source.pdf_page;dirty=false;await load();openCard(cards.find(c=>c.source.pdf_page===page));$('message').textContent='Saved. Character exports updated.';return true}catch(err){$('message').textContent=err.message;return false}finally{button.disabled=false;$('verify').disabled=false}}
$('save').onclick=saveReview;
$('verify').onclick=async()=>{const previous=Object.fromEntries(Object.entries(draft).map(([g,e])=>[g,e.status]));for(const g of Object.keys(groups)){draft[g].status='verified';touched.add(g)}dirty=true;$('verify').disabled=true;updateWholeStatus();if(!await saveReview()){for(const [g,status] of Object.entries(previous))draft[g].status=status;updateWholeStatus()}};
$('search').oninput=renderList;$('filter').onchange=renderList;$('zoom').oninput=()=>{$('card').style.width=$('zoom').value+'%'};
function advance(direction){if(!current)return;const i=cards.indexOf(current),c=cards[i+direction];if(c)openCard(c)}$('prev').onclick=()=>advance(-1);$('next').onclick=()=>advance(1);
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
// A small structured review surface for browsers that support imperative WebMCP.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'open_moonstone_card',description:'Open a Moonstone card by PDF page for review.',inputSchema:{type:'object',properties:{page:{type:'integer'}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:async({page})=>{if(!Number.isInteger(page))throw new Error('Page must be an integer');const c=cards.find(c=>c.source.pdf_page===page);if(!c)throw new Error('Unknown card');if(dirty)throw new Error('Save or discard pending edits first');openCard(c);return {page,name:c.name,review:c.review}}})).catch(()=>{})}catch{}}
load().then(()=>openCard(cards.find(c=>c.source.pdf_page===Number(new URLSearchParams(location.search).get('page')))||cards[0])).catch(e=>{$('name').textContent='Catalogue unavailable';$('message').textContent=e.message});
